    "source": "def knapsack_dp2d(weights: list[int], values: list[int], W: int) -> tuple[int, list[int]]:\n    \"\"\"0-1 knapsack DP 2D — complete Python reference. Returns (max_value, selected).\"\"\"\n    n = len(weights)\n    dp = [[0] * (W + 1) for _ in range(n + 1)]\n    for i in range(1, n + 1):\n        wt = weights[i - 1]\n        val = values[i - 1]\n        for w in range(W + 1):\n            dp[i][w] = dp[i - 1][w]\n            if w >= wt:\n                take = dp[i - 1][w - wt] + val\n                if take > dp[i][w]:\n                    dp[i][w] = take\n    selected: list[int] = []\n    w = W\n    for i in range(n, 0, -1):\n        if dp[i][w] != dp[i - 1][w]:\n            selected.append(i - 1)\n            w -= weights[i - 1]\n    selected.reverse()\n    return dp[n][W], selected\n",
