    "source": "// 0-1 knapsack DP 2D — complete C++17 reference.\n#include <algorithm>\n#include <utility>\n#include <vector>\n\nstd::pair<long long, std::vector<int>> knapsackDp2d(const std::vector<int>& weights, const std::vector<long long>& values, int W) {\n    int n = static_cast<int>(weights.size());\n    std::vector<std::vector<long long>> dp(n + 1, std::vector<long long>(W + 1, 0));\n    for (int i = 1; i <= n; i++) {\n        int wt = weights[i - 1];\n        long long val = values[i - 1];\n        for (int w = 0; w <= W; w++) {\n            dp[i][w] = dp[i - 1][w];\n            if (w >= wt) {\n                long long take = dp[i - 1][w - wt] + val;\n                if (take > dp[i][w]) dp[i][w] = take;\n            }\n        }\n    }\n    std::vector<int> selected;\n    int w = W;\n    for (int i = n; i >= 1; i--) {\n        if (dp[i][w] != dp[i - 1][w]) {\n            selected.push_back(i - 1);\n            w -= weights[i - 1];\n        }\n    }\n    std::reverse(selected.begin(), selected.end());\n    return {dp[n][W], selected};\n}\n",
