    "source": "import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\n\n/** 0-1 knapsack DP 2D — complete Java reference. */\npublic final class KnapsackDp2d {\n    public record Result(long maxValue, List<Integer> selected) {}\n\n    public static Result knapsackDp2d(int[] weights, long[] values, int W) {\n        int n = weights.length;\n        long[][] dp = new long[n + 1][W + 1];\n        for (int i = 1; i <= n; i++) {\n            int wt = weights[i - 1];\n            long val = values[i - 1];\n            for (int w = 0; w <= W; w++) {\n                dp[i][w] = dp[i - 1][w];\n                if (w >= wt) {\n                    long take = dp[i - 1][w - wt] + val;\n                    if (take > dp[i][w]) dp[i][w] = take;\n                }\n            }\n        }\n        List<Integer> selected = new ArrayList<>();\n        int w = W;\n        for (int i = n; i >= 1; i--) {\n            if (dp[i][w] != dp[i - 1][w]) {\n                selected.add(i - 1);\n                w -= weights[i - 1];\n            }\n        }\n        Collections.reverse(selected);\n        return new Result(dp[n][W], selected);\n    }\n}\n",
