    "source": "/// 0-1 knapsack DP 2D — complete Rust reference. Returns (max_value, selected).\npub fn knapsack_dp2d(weights: &[usize], values: &[i64], cap: usize) -> (i64, Vec<usize>) {\n    let n = weights.len();\n    let mut dp = vec![vec![0i64; cap + 1]; n + 1];\n    for i in 1..=n {\n        let wt = weights[i - 1];\n        let val = values[i - 1];\n        for w in 0..=cap {\n            dp[i][w] = dp[i - 1][w];\n            if w >= wt {\n                let take = dp[i - 1][w - wt] + val;\n                if take > dp[i][w] { dp[i][w] = take; }\n            }\n        }\n    }\n    let mut selected: Vec<usize> = Vec::new();\n    let mut w = cap;\n    for i in (1..=n).rev() {\n        if dp[i][w] != dp[i - 1][w] {\n            selected.push(i - 1);\n            w -= weights[i - 1];\n        }\n    }\n    selected.reverse();\n    (dp[n][cap], selected)\n}\n",
