    "source": "package algorithms\n\n// knapsackDp2d — 0-1 knapsack DP 2D, complete Go reference. Returns (maxValue, selected).\nfunc knapsackDp2d(weights, values []int, W int) (int, []int) {\n\tn := len(weights)\n\tdp := make([][]int, n+1)\n\tfor i := range dp {\n\t\tdp[i] = make([]int, W+1)\n\t}\n\tfor i := 1; i <= n; i++ {\n\t\twt := weights[i-1]\n\t\tval := values[i-1]\n\t\tfor w := 0; w <= W; w++ {\n\t\t\tdp[i][w] = dp[i-1][w]\n\t\t\tif w >= wt {\n\t\t\t\ttake := dp[i-1][w-wt] + val\n\t\t\t\tif take > dp[i][w] {\n\t\t\t\t\tdp[i][w] = take\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tselected := []int{}\n\tw := W\n\tfor i := n; i >= 1; i-- {\n\t\tif dp[i][w] != dp[i-1][w] {\n\t\t\tselected = append(selected, i-1)\n\t\t\tw -= weights[i-1]\n\t\t}\n\t}\n\tfor l, r := 0, len(selected)-1; l < r; l, r = l+1, r-1 {\n\t\tselected[l], selected[r] = selected[r], selected[l]\n\t}\n\treturn dp[n][W], selected\n}\n",
